.tmp/arena-creation/survivor-input/alloc.content:
export function reserve(stock, requests) {
  const remaining = stock.map(item => ({...item}));
  const decisions = requests.map(({sku, quantity}) => {
    const item = remaining.find(value => value.sku === sku);
    const accepted = Boolean(item && item.quantity >= quantity);
    if (item) item.quantity -= quantity;
    return {sku, quantity, accepted};
  });
  return {stock: remaining, decisions};
}

