import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const {reserve} = await import(pathToFileURL(process.argv[2]));
const results = [];
function check(name, run) {
  try { run(); results.push({name, pass:true}); }
  catch (error) { results.push({name, pass:false, error:error.message}); }
}
check('empty inputs', () => assert.deepEqual(reserve([], []), {stock:[],decisions:[]}));
check('ordered reservations and denial preserve remaining quantity', () => assert.deepEqual(
  reserve([{sku:'a',quantity:5}], [{sku:'a',quantity:3},{sku:'a',quantity:3},{sku:'a',quantity:2}]),
  {stock:[{sku:'a',quantity:0}],decisions:[{sku:'a',quantity:3,accepted:true},{sku:'a',quantity:3,accepted:false},{sku:'a',quantity:2,accepted:true}]}));
check('zero quantities and unknown SKUs', () => assert.deepEqual(
  reserve([{sku:'a',quantity:0}], [{sku:'a',quantity:0},{sku:'missing',quantity:0},{sku:'a',quantity:1}]),
  {stock:[{sku:'a',quantity:0}],decisions:[{sku:'a',quantity:0,accepted:true},{sku:'missing',quantity:0,accepted:false},{sku:'a',quantity:1,accepted:false}]}));
check('stock order, request order and case sensitivity', () => assert.deepEqual(
  reserve([{sku:'B',quantity:2},{sku:'a',quantity:4}], [{sku:'b',quantity:1},{sku:'a',quantity:4},{sku:'B',quantity:1}]),
  {stock:[{sku:'B',quantity:1},{sku:'a',quantity:0}],decisions:[{sku:'b',quantity:1,accepted:false},{sku:'a',quantity:4,accepted:true},{sku:'B',quantity:1,accepted:true}]}));
check('property-like SKUs', () => assert.deepEqual(
  reserve([{sku:'__proto__',quantity:2},{sku:'constructor',quantity:1}], [{sku:'__proto__',quantity:1},{sku:'toString',quantity:0}]),
  {stock:[{sku:'__proto__',quantity:1},{sku:'constructor',quantity:1}],decisions:[{sku:'__proto__',quantity:1,accepted:true},{sku:'toString',quantity:0,accepted:false}]}));
check('safe integer boundary', () => assert.deepEqual(reserve([{sku:'x',quantity:Number.MAX_SAFE_INTEGER}], [{sku:'x',quantity:Number.MAX_SAFE_INTEGER}]).stock,[{sku:'x',quantity:0}]));
check('immutable frozen inputs and new records', () => {
  const stock=Object.freeze([Object.freeze({sku:'a',quantity:2})]);
  const req=Object.freeze([Object.freeze({sku:'a',quantity:1})]);
  const out=reserve(stock,req);
  assert.deepEqual(stock,[{sku:'a',quantity:2}]);assert.deepEqual(req,[{sku:'a',quantity:1}]);
  assert.notEqual(out.stock,stock);assert.notEqual(out.stock[0],stock[0]);assert.notEqual(out.decisions[0],req[0]);
});
check('ignores extra record fields', () => assert.deepEqual(reserve([{sku:'a',quantity:1,extra:7}],[{sku:'a',quantity:1,extra:3}]),{stock:[{sku:'a',quantity:0}],decisions:[{sku:'a',quantity:1,accepted:true}]}));
check('rejects non-array inputs', () => {for (const v of [undefined,null,{},'x',1]) {assert.throws(()=>reserve(v,[]),TypeError);assert.throws(()=>reserve([],v),TypeError);}});
check('rejects invalid records and fields', () => {for(const v of [null,undefined,[],{sku:'',quantity:1},{sku:3,quantity:1},{sku:'a',quantity:-1},{sku:'a',quantity:0.5},{sku:'a',quantity:Infinity},{sku:'a',quantity:NaN},{sku:'a',quantity:Number.MAX_SAFE_INTEGER+1},{sku:'a',quantity:'1'}]) {assert.throws(()=>reserve([v],[]),TypeError);assert.throws(()=>reserve([],[v]),TypeError);}});
check('rejects duplicate stock, permits repeated requests', () => {assert.throws(()=>reserve([{sku:'a',quantity:1},{sku:'a',quantity:2}],[]),TypeError);assert.equal(reserve([{sku:'a',quantity:2}],[{sku:'a',quantity:1},{sku:'a',quantity:1}]).decisions.length,2);});
check('error leaves inputs unchanged', () => {const stock=[{sku:'a',quantity:3}];const req=[{sku:'a',quantity:1},{sku:'a',quantity:-1}];assert.throws(()=>reserve(stock,req),TypeError);assert.deepEqual(stock,[{sku:'a',quantity:3}]);assert.deepEqual(req,[{sku:'a',quantity:1},{sku:'a',quantity:-1}]);});
console.log(JSON.stringify({passed:results.filter(x=>x.pass).length,total:results.length,results},null,2));
if(results.some(x=>!x.pass)) process.exitCode=1;

