/**
 * Reserves stock against a list of requests, processed in request order.
 *
 * @param {ReadonlyArray<{ sku: string, quantity: number }>} stock
 *   Unique SKUs with nonnegative safe-integer quantities.
 * @param {ReadonlyArray<{ sku: string, quantity: number }>} requests
 *   Requests in processing order; SKUs may repeat.
 * @returns {{
 *   stock: Array<{ sku: string, quantity: number }>,
 *   decisions: Array<{ sku: string, quantity: number, accepted: boolean }>,
 * }}
 *   Fresh records: remaining stock in original order, one decision per request.
 * @throws {TypeError}
 *   When an input is not an array, a record or field is malformed, or stock repeats a SKU.
 */
export function reserve(stock, requests) {
  assertArray(stock, "stock");
  assertArray(requests, "requests");

  const remaining = new Map();
  const stockSkus = [];
  for (let index = 0; index < stock.length; index += 1) {
    const { sku, quantity } = readRecord(stock[index], `stock[${index}]`);
    if (remaining.has(sku)) {
      throw new TypeError(
        `stock[${index}].sku ${JSON.stringify(sku)} duplicates an earlier stock sku`,
      );
    }
    remaining.set(sku, quantity);
    stockSkus.push(sku);
  }

  const requestRecords = [];
  for (let index = 0; index < requests.length; index += 1) {
    requestRecords.push(readRecord(requests[index], `requests[${index}]`));
  }

  const decisions = requestRecords.map(({ sku, quantity }) => {
    const available = remaining.get(sku);
    const accepted = available !== undefined && available >= quantity;
    if (accepted) {
      remaining.set(sku, available - quantity);
    }
    return { sku, quantity, accepted };
  });

  return {
    stock: stockSkus.map((sku) => ({ sku, quantity: remaining.get(sku) })),
    decisions,
  };
}

function assertArray(value, name) {
  if (!Array.isArray(value)) {
    throw new TypeError(`${name} must be an array`);
  }
}

function readRecord(record, location) {
  if (record === null || typeof record !== "object" || Array.isArray(record)) {
    throw new TypeError(`${location} must be an object`);
  }
  const { sku, quantity } = record;
  if (typeof sku !== "string" || sku.length === 0) {
    throw new TypeError(`${location}.sku must be a nonempty string`);
  }
  if (!Number.isSafeInteger(quantity) || quantity < 0) {
    throw new TypeError(`${location}.quantity must be a nonnegative safe integer`);
  }
  // -0 passes the checks above; fold it so output records never carry a negative zero.
  return { sku, quantity: Object.is(quantity, -0) ? 0 : quantity };
}

