/**
 * Reserve stock for a sequence of requests, processed in order.
 *
 * @param {ReadonlyArray<{ sku: string, quantity: number }>} stock
 * @param {ReadonlyArray<{ sku: string, quantity: number }>} requests
 * @returns {{
 *   stock: Array<{ sku: string, quantity: number }>,
 *   decisions: Array<{ sku: string, quantity: number, accepted: boolean }>,
 * }}
 */
export function reserve(stock, requests) {
  const stockRecords = readRecords(stock, "stock");
  const requestRecords = readRecords(requests, "requests");

  const remaining = new Map();
  stockRecords.forEach(({ sku, quantity }, index) => {
    if (remaining.has(sku)) {
      throw new TypeError(
        `stock[${index}].sku ${JSON.stringify(sku)} duplicates an earlier stock SKU`,
      );
    }
    remaining.set(sku, quantity);
  });

  const decisions = requestRecords.map(({ sku, quantity }) => {
    const accepted = remaining.has(sku) && remaining.get(sku) >= quantity;
    if (accepted) {
      remaining.set(sku, remaining.get(sku) - quantity);
    }
    return { sku, quantity, accepted };
  });

  return {
    stock: stockRecords.map(({ sku }) => ({ sku, quantity: remaining.get(sku) })),
    decisions,
  };
}

function readRecords(list, name) {
  if (!Array.isArray(list)) {
    throw new TypeError(`${name} must be an array`);
  }
  const records = [];
  for (let index = 0; index < list.length; index += 1) {
    records.push(readRecord(list[index], `${name}[${index}]`));
  }
  return records;
}

function readRecord(record, label) {
  if (record === null || typeof record !== "object") {
    throw new TypeError(`${label} must be an object`);
  }
  const { sku, quantity } = record;
  if (typeof sku !== "string" || sku.length === 0) {
    throw new TypeError(`${label}.sku must be a nonempty string`);
  }
  if (!Number.isSafeInteger(quantity) || quantity < 0) {
    throw new TypeError(`${label}.quantity must be a nonnegative safe integer`);
  }
  // `+ 0` folds -0 (a nonnegative safe integer) into 0 so outputs never carry a signed zero.
  return { sku, quantity: quantity + 0 };
}

