// Contract probe for the surviving candidate A (allocate.mjs). Read-only import; the artifact is not modified.
import * as mod from "../survivor-input/allocate.mjs";

const { reserve } = mod;
const results = [];
const record = (clause, pass, detail) => results.push({ clause, pass, detail });
const json = (v) => JSON.stringify(v);
const deepFreeze = (v) => {
  if (v && typeof v === "object") {
    Object.freeze(v);
    for (const k of Object.keys(v)) deepFreeze(v[k]);
  }
  return v;
};
const run = (stock, requests) => {
  try {
    return { ok: true, value: reserve(stock, requests) };
  } catch (error) {
    return { ok: false, error };
  }
};

// Module shape
record("exports named reserve function", typeof reserve === "function", `typeof reserve = ${typeof reserve}; export keys = ${json(Object.keys(mod))}`);

// Happy path with a denied request in the middle
{
  const stock = [{ sku: "a", quantity: 5 }, { sku: "b", quantity: 2 }];
  const requests = [
    { sku: "a", quantity: 3 },
    { sku: "b", quantity: 5 },
    { sku: "c", quantity: 0 },
    { sku: "a", quantity: 0 },
    { sku: "a", quantity: 2 },
  ];
  const expected = {
    stock: [{ sku: "a", quantity: 0 }, { sku: "b", quantity: 2 }],
    decisions: [
      { sku: "a", quantity: 3, accepted: true },
      { sku: "b", quantity: 5, accepted: false },
      { sku: "c", quantity: 0, accepted: false },
      { sku: "a", quantity: 0, accepted: true },
      { sku: "a", quantity: 2, accepted: true },
    ],
  };
  const r = run(stock, requests);
  record("decisions: accept/deny, zero-known accepted, zero-unknown denied", r.ok && json(r.value.decisions) === json(expected.decisions), r.ok ? `got decisions ${json(r.value.decisions)}` : String(r.error));
  record("denied request leaves stock unchanged (final stock)", r.ok && json(r.value.stock) === json(expected.stock), r.ok ? `expected ${json(expected.stock)} got ${json(r.value.stock)}` : String(r.error));
}

// Denied request followed by one that would fit
{
  const stock = [{ sku: "a", quantity: 5 }];
  const requests = [{ sku: "a", quantity: 6 }, { sku: "a", quantity: 5 }];
  const r = run(stock, requests);
  const expectedDecisions = [
    { sku: "a", quantity: 6, accepted: false },
    { sku: "a", quantity: 5, accepted: true },
  ];
  record("denied request does not affect later acceptance", r.ok && json(r.value.decisions) === json(expectedDecisions) && json(r.value.stock) === json([{ sku: "a", quantity: 0 }]), r.ok ? `got stock ${json(r.value.stock)} decisions ${json(r.value.decisions)}` : String(r.error));
}

// Input immutability (frozen inputs must not throw; plain inputs must be byte-identical after)
{
  const stock = [{ sku: "a", quantity: 5 }, { sku: "b", quantity: 2 }];
  const requests = [{ sku: "a", quantity: 3 }, { sku: "b", quantity: 9 }];
  const before = json({ stock, requests });
  const r = run(stock, requests);
  record("inputs not mutated (plain objects)", r.ok && json({ stock, requests }) === before, r.ok ? `after ${json({ stock, requests })}` : String(r.error));
  const frozen = run(deepFreeze([{ sku: "a", quantity: 5 }]), deepFreeze([{ sku: "a", quantity: 3 }, { sku: "a", quantity: 9 }]));
  record("inputs not mutated (deep-frozen inputs, no throw)", frozen.ok, frozen.ok ? "no throw" : String(frozen.error));
  if (r.ok) {
    record("returned stock records are new objects", r.value.stock.every((item, i) => item !== stock[i]), "reference inequality checked");
    record("returned decision records are new objects", r.value.decisions.every((d, i) => d !== requests[i]), "reference inequality checked");
  }
}

// Empty inputs
