/**
 * Reserve requested quantities against stock, processing requests in order.
 *
 * @param {ReadonlyArray<{sku: string, quantity: number}>} stock
 * @param {ReadonlyArray<{sku: string, quantity: number}>} requests
 * @returns {{
 *   stock: Array<{sku: string, quantity: number}>,
 *   decisions: Array<{sku: string, quantity: number, accepted: boolean}>,
 * }}
 * @throws {TypeError} on invalid arrays, records, field values, or duplicate stock SKUs.
 */
export function reserve(stock, requests) {
  const stockLines = readLines(stock, 'stock');
  const remaining = indexStock(stockLines);
  const requestLines = readLines(requests, 'requests');

  const decisions = [];
  for (const { sku, quantity } of requestLines) {
    const available = remaining.get(sku);
    const accepted = available !== undefined && quantity <= available;
    if (accepted) {
      remaining.set(sku, available - quantity);
    }
    decisions.push({ sku, quantity, accepted });
  }

  const finalStock = stockLines.map(({ sku }) => ({ sku, quantity: remaining.get(sku) }));
  return { stock: finalStock, decisions };
}

// Validates every record up front and copies the two fields out, so later
// phases never touch caller objects and each getter is read exactly once.
function readLines(list, name) {
  if (!Array.isArray(list)) {
    throw new TypeError(`reserve: ${name} must be an array`);
  }
  const length = list.length;
  const lines = [];
  for (let index = 0; index < length; index += 1) {
    const record = list[index];
    if (record === null || typeof record !== 'object' || Array.isArray(record)) {
      throw new TypeError(`reserve: ${name}[${index}] must be a record object`);
    }
    const sku = record.sku;
    if (typeof sku !== 'string' || sku.length === 0) {
      throw new TypeError(`reserve: ${name}[${index}].sku must be a nonempty string`);
    }
    const quantity = record.quantity;
    if (!Number.isSafeInteger(quantity) || quantity < 0) {
      throw new TypeError(`reserve: ${name}[${index}].quantity must be a nonnegative safe integer`);
    }
    // `+ 0` folds -0 into +0 so the sign never leaks into results.
    lines.push({ sku, quantity: quantity + 0 });
  }
  return lines;
}

// A Map keeps property-like SKUs such as "__proto__" or "constructor" ordinary keys.
function indexStock(stockLines) {
  const remaining = new Map();
  for (let index = 0; index < stockLines.length; index += 1) {
    const { sku, quantity } = stockLines[index];
    if (remaining.has(sku)) {
      throw new TypeError(`reserve: duplicate stock sku ${JSON.stringify(sku)} at stock[${index}]`);
    }
    remaining.set(sku, quantity);
  }
  return remaining;
}

