const isObjectLike = (value) => Object(value) === value;
const isSku = (value) => typeof value === 'string' && value.length > 0;
const isQuantity = (value) =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

// Reads each field exactly once and copies it, so later getter calls or
// mutations by the caller cannot change what is processed.
function readRecord(record, label, index) {
  if (!isObjectLike(record)) {
    throw new TypeError(`${label}[${index}] must be an object record`);
  }
  const { sku, quantity } = record;
  if (!isSku(sku)) {
    throw new TypeError(`${label}[${index}].sku must be a nonempty string`);
  }
  if (!isQuantity(quantity)) {
    throw new TypeError(
      `${label}[${index}].quantity must be a nonnegative safe integer`,
    );
  }
  return { sku, quantity: quantity === 0 ? 0 : quantity };
}

function readRecords(array, label) {
  if (!Array.isArray(array)) {
    throw new TypeError(`${label} must be an array`);
  }
  const records = [];
  for (let index = 0; index < array.length; index += 1) {
    records.push(readRecord(array[index], label, index));
  }
  return records;
}

function buildRemaining(stockRecords) {
  const remaining = new Map();
  stockRecords.forEach(({ sku, quantity }, index) => {
    if (remaining.has(sku)) {
      throw new TypeError(`stock[${index}].sku ${JSON.stringify(sku)} is a duplicate`);
    }
    remaining.set(sku, quantity);
  });
  return remaining;
}

export function reserve(stock, requests) {
  const stockRecords = readRecords(stock, 'stock');
  const remaining = buildRemaining(stockRecords);
  const requestRecords = readRecords(requests, 'requests');

  const decisions = requestRecords.map(({ sku, quantity }) => {
    const available = remaining.get(sku);
    const accepted = available !== undefined && quantity <= available;
    if (accepted) {
      remaining.set(sku, available - quantity);
    }
    return { sku, quantity, accepted };
  });

  return {
    stock: stockRecords.map(({ sku }) => ({ sku, quantity: remaining.get(sku) })),
    decisions,
  };
}

