// Acceptance probe for readCount candidates. Usage: node probe.mjs <module.mjs>...
import { builtinModules } from 'node:module';
import { readFileSync } from 'node:fs';
import { resolve, basename } from 'node:path';
import { pathToFileURL } from 'node:url';
import { format } from 'node:util';

const MAX_SAFE = Number.MAX_SAFE_INTEGER;

// [label, JSON text, expectation]. expectation: { returns } compared with Object.is, or { throws: true }.
const cases = [
  ['zero', '{"count":0}', { returns: 0 }],
  ['one', '{"count":1}', { returns: 1 }],
  ['typical', '{"count":42}', { returns: 42 }],
  ['max safe integer', `{"count":${MAX_SAFE}}`, { returns: MAX_SAFE }],
  ['integral float literal 5.0', '{"count":5.0}', { returns: 5 }],
  ['exponent literal 1e3', '{"count":1e3}', { returns: 1000 }],
  ['negative zero literal (-0 is a safe integer and not < 0)', '{"count":-0}', { returns: -0 }],
  ['absent', '{}', { throws: true }],
  ['other keys only', '{"Count":1,"counts":1}', { throws: true }],
  ['null', '{"count":null}', { throws: true }],
  ['numeric string "5"', '{"count":"5"}', { throws: true }],
  ['empty string', '{"count":""}', { throws: true }],
  ['true', '{"count":true}', { throws: true }],
  ['false', '{"count":false}', { throws: true }],
  ['negative', '{"count":-1}', { throws: true }],
  ['fraction', '{"count":1.5}', { throws: true }],
  ['2^53 (unsafe)', `{"count":${MAX_SAFE + 1}}`, { throws: true }],
  ['overflow to Infinity', '{"count":1e400}', { throws: true }],
  ['overflow to -Infinity', '{"count":-1e400}', { throws: true }],
  ['object', '{"count":{"count":1}}', { throws: true }],
  ['empty array', '{"count":[]}', { throws: true }],
  ['array', '{"count":[1]}', { throws: true }],
];

function importSpecifiers(source) {
  const out = [];
  const re = /\bimport\b[^'"]*?['"]([^'"]+)['"]|\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
  for (const m of source.matchAll(re)) out.push(m[1] ?? m[2]);
  return out;
}

async function probe(path) {
  const name = basename(path);
  const source = readFileSync(path, 'utf8');
  const specifiers = importSpecifiers(source);
  const foreign = specifiers.filter((s) => !builtinModules.includes(s.replace(/^node:/, '')));
  const lines = [];
  let failures = 0;

  const mod = await import(pathToFileURL(resolve(path)).href);
  const { readCount } = mod;
  lines.push(`exports: ${Object.keys(mod).join(', ')}; readCount is ${typeof readCount}`);
  if (typeof readCount !== 'function') return { name, failures: 1, lines: [...lines, 'FAIL H3 no readCount export'] };

  for (const [label, json, expect] of cases) {
    const record = JSON.parse(json);
    const before = JSON.stringify(record);
    let outcome;
    try {
      outcome = { returned: readCount(record) };
    } catch (error) {
      outcome = { threw: error };
    }
    const preserved = JSON.stringify(record) === before;
    let ok;
    let detail;
    if ('returns' in expect) {
      ok = 'returned' in outcome && Object.is(outcome.returned, expect.returns);
      detail = 'returned' in outcome ? `returned ${format('%o', outcome.returned)}` : `threw ${outcome.threw?.constructor?.name}: ${outcome.threw?.message}`;
    } else {
      const e = outcome.threw;
      ok = 'threw' in outcome && e instanceof TypeError;
      detail = 'threw' in outcome
        ? `threw ${e?.constructor?.name} (instanceof TypeError: ${e instanceof TypeError}, name: ${e?.name}): ${e?.message}`
        : `returned ${format('%o', outcome.returned)}`;
    }
    if (!preserved) { ok = false; detail += ' | INPUT MUTATED'; }
    if (!ok) failures += 1;
    lines.push(`${ok ? 'pass' : 'FAIL'}  ${label.padEnd(58)} ${detail}`);
  }

  // Informational, outside the contract domain: resolves the supplied judge's throwing-getter claim.
  const exotic = { get count() { throw new RangeError('getter'); } };
  let exoticDetail;
