// Arena probe: checks every candidate and the final module against contract.txt.
// Hard constraints H1-H5 come from the contract; "info" rows are out-of-domain observations only.
import { readFileSync } from 'node:fs';
import { isBuiltin } from 'node:module';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const modules = {
  A: resolve(here, '../criteria-input/a.mjs'),
  B: resolve(here, '../criteria-input/b.mjs'),
  C: resolve(here, '../criteria-input/c.mjs'),
  FINAL: resolve(here, 'read-count.mjs'),
};

const valid = [
  ['{"count":0}', 0],
  ['{"count":7}', 7],
  ['{"count":9007199254740991}', Number.MAX_SAFE_INTEGER],
  ['{"count":-0}', -0],
  ['{"count":3,"other":"x"}', 3],
];
const invalid = [
  '{}',
  '{"count":null}',
  '{"count":true}',
  '{"count":false}',
  '{"count":"5"}',
  '{"count":""}',
  '{"count":-1}',
  '{"count":1.5}',
  '{"count":9007199254740992}',
  '{"count":1e21}',
  '{"count":[]}',
  '{"count":[1]}',
  '{"count":{}}',
  '{"count":{"toString":1,"valueOf":2}}',
  '{"Count":1}',
];

function importSpecifiers(source) {
  return [...source.matchAll(/^\s*import\b[^'"]*['"]([^'"]+)['"]/gm)].map((m) => m[1]);
}

let finalFailed = false;
for (const [label, path] of Object.entries(modules)) {
  const source = readFileSync(path, 'utf8');
  const mod = await import(path);
  const { readCount } = mod;
  const failures = [];
  const notes = [];

  // H1: ES module exporting readCount
  if (typeof readCount !== 'function') failures.push('H1 export: readCount is not an exported function');

  // H2: dependency-free; JavaScript and Node built-ins only
  const specs = importSpecifiers(source);
  const external = specs.filter((s) => !isBuiltin(s));
  if (external.length) failures.push(`H2 dependencies: non-built-in import(s) ${external.join(', ')}`);
  notes.push(`imports: ${specs.length ? specs.join(', ') : 'none'}`);

  // H3: returns record.count for nonnegative safe integers; H5: input preserved
  for (const [json, expected] of valid) {
    const record = JSON.parse(json);
    const before = JSON.stringify(record);
    let result;
    try {
      result = readCount(record);
    } catch (e) {
      failures.push(`H3 valid ${json}: threw ${e?.constructor?.name}: ${e?.message}`);
      continue;
    }
    if (!Object.is(result, expected) && !(result === 0 && expected === 0)) {
      failures.push(`H3 valid ${json}: returned ${String(result)}, expected ${String(expected)}`);
    }
    if (Object.is(expected, -0)) notes.push(`-0 input returns ${Object.is(result, -0) ? '-0' : String(result)}`);
    if (JSON.stringify(record) !== before) failures.push(`H5 preserve ${json}: input changed to ${JSON.stringify(record)}`);
    const frozen = Object.freeze(JSON.parse(json));
    try {
      const frozenResult = readCount(frozen);
      if (!Object.is(frozenResult, result)) failures.push(`H5 preserve ${json}: frozen input gave a different result`);
    } catch (e) {
      failures.push(`H5 preserve ${json}: frozen input threw ${e?.constructor?.name}: ${e?.message}`);
    }
  }

  // H4: absent or invalid count throws a TypeError or subclass; H5 again
  const messages = [];
  for (const json of invalid) {
    const record = JSON.parse(json);
    const before = JSON.stringify(record);
    try {
      const result = readCount(record);
      failures.push(`H4 invalid ${json}: returned ${String(result)} instead of throwing`);
    } catch (e) {
      if (!(e instanceof TypeError)) failures.push(`H4 invalid ${json}: threw ${e?.constructor?.name} (not a TypeError): ${e?.message}`);
      messages.push(`${json} -> ${e?.constructor?.name}: ${e?.message}`);
    }
    if (JSON.stringify(record) !== before) failures.push(`H5 preserve ${json}: input changed`);
  }

  // info only: out-of-domain inputs the supplied judge cited (accessors). Not scored.
  const info = [];
  try {
    readCount({ get count() { throw new RangeError('getter'); } });
    info.push('throwing getter: returned without throwing');
  } catch (e) {
    info.push(`throwing getter: propagates ${e?.constructor?.name}`);
  }
  try {
    const r = readCount(new Proxy({}, { get: () => 4 }));
    info.push(`proxy returning 4: returned ${String(r)}`);
  } catch (e) {
    info.push(`proxy returning 4: threw ${e?.constructor?.name}`);
  }

  console.log(`\n=== ${label} (${path}) ===`);
  console.log(`result: ${failures.length ? 'FAIL' : 'PASS'} (${valid.length} valid + ${invalid.length} invalid in-domain cases)`);
  for (const f of failures) console.log(`  FAIL ${f}`);
  for (const n of notes) console.log(`  note ${n}`);
  for (const i of info) console.log(`  info (out of domain) ${i}`);
  console.log('  messages:');
  for (const m of messages) console.log(`    ${m}`);
  if (label === 'FINAL' && failures.length) finalFailed = true;
}
process.exitCode = finalFailed ? 1 : 0;

