export function readCount(record) {
  const count = record.count;
  if (count === undefined) throw new TypeError('count is absent');
  if (!Number.isSafeInteger(count) || count < 0) {
    throw new TypeError(`count must be a nonnegative safe integer, got ${describe(count)}`);
  }
  return count;
}

// Never converts objects: a JSON-decoded object may carry non-callable
// toString/valueOf keys, and traversing it would only obscure the real defect.
function describe(value) {
  if (value !== null && typeof value === 'object') return Array.isArray(value) ? 'an array' : 'an object';
  return typeof value === 'string' ? JSON.stringify(value) : String(value);
}

